```tsx
'use client';
import { useState, useEffect, useRef, useCallback } from 'react';
import { Document, Page, pdfjs } from 'react-pdf';

// PDF.js worker
pdfjs.GlobalWorkerOptions.workerSrc = `//unpkg.com/pdfjs-dist@${pdfjs.version}/build/pdf.worker.min.mjs`;

export interface PDFViewerProps {
  pdfId: string;
  highlights?: string[];
}

interface HighlightBox {
  id: string;
  page: number;
  left: number;
  top: number;
  width: number;
  height: number;
  color?: string;
}

export function PDFViewer({ pdfId, highlights = [] }: PDFViewerProps) {
  const [numPages, setNumPages] = useState<number>(0);
  const [currentPage, setCurrentPage] = useState<number>(1);
  const [pdfUrl, setPdfUrl] = useState<string>('');
  const [highlightBoxes, setHighlightBoxes] = useState<HighlightBox[]>([]);
  const containerRef = useRef<HTMLDivElement>(null);
  const pdfRef = useRef<any>(null);

  // Fetch PDF URL
  useEffect(() => {
    const fetchPdf = async () => {
      try {
        const response = await fetch(`/api/pdf/${pdfId}`);
        if (response.ok) {
          const json = await response.json();
          setPdfUrl(json.filePath);
        } else {
          console.error('Failed to fetch PDF:', response.status);
        }
      } catch (err) {
        console.error('Error fetching PDF:', err);
      }
    };
    fetchPdf();
  }, [pdfId]);

  // Normalize text: remove spaces, punctuation, and convert to lowercase
  const normalizeText = (text: string) => {
    return text
      .toLowerCase()
      .replace(/[\n\r\s:;,.\/•–—]+/g, '') // Remove spaces and punctuation
      .trim();
  };

  // Get scale factor from CSS variable
  const getScaleFactor = (element: HTMLElement): number => {
    const style = window.getComputedStyle(element);
    const scaleFactor = style.getPropertyValue('--total-scale-factor').trim();
    return parseFloat(scaleFactor) || 1;
  };

  // Find the rendered page DOM element
  const findRenderedPageElement = useCallback((): HTMLElement | null => {
    if (!containerRef.current) return null;
    return containerRef.current.querySelector('.react-pdf__Page') as HTMLElement | null;
  }, []);

  // Compute highlights using DOM text layer
  const computeHighlightsFromDOM = useCallback(
    (highlightTexts: string[]) => {
      const pageEl = findRenderedPageElement();
      if (!pageEl) {
        console.warn('No rendered page DOM found when computing highlights.');
        setHighlightBoxes([]);
        return;
      }

      const containerRect = pageEl.getBoundingClientRect();
      const scaleFactor = getScaleFactor(pageEl);
      console.log('Scale factor:', scaleFactor);
      const foundBoxes: HighlightBox[] = [];

      // Get all <span> elements in the text layer
      const textLayer = pageEl.querySelector('.react-pdf__Page__textContent') as HTMLElement | null;
      const textElements = Array.from(textLayer ? textLayer.querySelectorAll('span') : []).filter(
        (el): el is HTMLSpanElement => {
          const style = window.getComputedStyle(el);
          return style.display !== 'none' && style.visibility !== 'hidden' && style.opacity !== '0';
        }
      );

      // Log text content for debugging
      const allText = textElements.map((el) => el.textContent || '').join(' ');
      console.log('DOM Page text:', {
        page: currentPage,
        text: allText,
        elementCount: textElements.length,
        rawElements: textElements.map((el) => ({
          text: el.textContent,
          style: {
            left: el.style.left,
            top: el.style.top,
            transform: el.style.transform,
          },
        })),
      });

      highlightTexts.forEach((rawText) => {
        const normalizedTarget = normalizeText(rawText);
        if (!normalizedTarget) {
          console.warn('Empty normalized target text, skipping:', rawText);
          return;
        }

        // First, try single <span> matching
        let matchedElements: HTMLSpanElement[] = [];
        let matchedText = '';

        const matchedEl = textElements.find((el) => {
          const text = normalizeText(el.textContent || '');
          return text.includes(normalizedTarget);
        });

        if (matchedEl) {
          matchedElements = [matchedEl];
          matchedText = normalizeText(matchedEl.textContent || '');
        }

        // Fallback to sliding window if no single match
        if (matchedElements.length === 0) {
          for (let i = 0; i < textElements.length; i++) {
            let currentText = '';
            let currentElements: HTMLSpanElement[] = [];

            for (let j = i; j < Math.min(i + 3, textElements.length); j++) {
              const el = textElements[j];
              currentElements.push(el);
              currentText = normalizeText(currentElements.map((e) => e.textContent || '').join(''));

              if (currentText.includes(normalizedTarget)) {
                matchedElements = [...currentElements];
                matchedText = currentText;
                break;
              }
            }

            if (matchedElements.length) break;
          }
        }

        if (matchedElements.length === 0) {
          console.warn(`No DOM match for "${rawText}" on page ${currentPage}`, {
            normalizedTarget,
            availableText: textElements.map((el) => normalizeText(el.textContent || '')).join(' | '),
          });
          // Fallback to PDF.js
          if (pdfRef.current) {
            (async () => {
              for (let pageNum = 1; pageNum <= numPages; pageNum++) {
                try {
                  const page = await pdfRef.current.getPage(pageNum);
                  const textContent = await page.getTextContent();
                  const rawText = textContent.items.map((item: any) => item.str).join(' ');
                  const fullText = normalizeText(rawText);
                  console.log('PDF.js extracted text for page', pageNum, { rawText, normalized: fullText });

                  if (fullText.includes(normalizedTarget)) {
                    console.log(`Text "${rawText}" found on page ${pageNum} via PDF.js, navigating...`);
                    setCurrentPage(pageNum);
                    setTimeout(() => computeHighlightsFromDOM(highlightTexts), 1000);
                    return;
                  }
                } catch (err) {
                  console.error(`Error processing page ${pageNum}:`, err);
                }
              }
            })();
          }
          return;
        }

        // Compute bounding box
        const rects = matchedElements.map((el) => {
          const rect = el.getBoundingClientRect();
          const style = window.getComputedStyle(el);
          const transform = style.transform || style.webkitTransform;
          let x = rect.left;
          let y = rect.top;

          // Adjust for CSS transform
          if (transform && transform !== 'none') {
            const matrix = transform.match(/matrix\((.+)\)/)?.[1].split(',').map(Number);
            if (matrix && matrix.length >= 6) {
              x += matrix[4];
              y += matrix[5];
              const scaleX = matrix[0] || 1;
              const scaleY = matrix[3] || 1;
              x /= scaleX;
              y /= scaleY;
            }
          }

          // Adjust for CSS left/top with var(--total-scale-factor)
          const leftMatch = el.style.left.match(/calc\(var\(--total-scale-factor\) \*\s*([\d.]+)px\)/);
          const topMatch = el.style.top.match(/calc\(var\(--total-scale-factor\) \*\s*([\d.]+)px\)/);
          if (leftMatch && topMatch) {
            x = parseFloat(leftMatch[1]) * scaleFactor;
            y = parseFloat(topMatch[1]) * scaleFactor;
          }

          return { ...rect, left: x, top: y };
        });

        const left = Math.min(...rects.map((r) => r.left));
        const top = Math.min(...rects.map((r) => r.top));
        const right = Math.max(...rects.map((r) => r.right));
        const bottom = Math.max(...rects.map((r) => r.bottom));

        const relativeLeft = (left - containerRect.left + pageEl.scrollLeft) / scaleFactor;
        const relativeTop = (top - containerRect.top + pageEl.scrollTop) / scaleFactor;

        foundBoxes.push({
          id: `${rawText}-${currentPage}-${foundBoxes.length}`,
          page: currentPage,
          left: Math.max(0, relativeLeft),
          top: Math.max(0, relativeTop),
          width: Math.max(2, (right - left) / scaleFactor),
          height: Math.max(2, (bottom - top) / scaleFactor),
          color: 'rgba(255, 255, 0, 0.5)', // Increased opacity for visibility
        });

        console.log('Highlight matched:', {
          rawText,
          matchedText,
          elements: matchedElements.length,
          box: { left: relativeLeft, top: relativeTop, width: (right - left) / scaleFactor, height: (bottom - top) / scaleFactor },
          rects,
          containerRect,
          scaleFactor,
        });
      });

      setHighlightBoxes((prev) => {
        const prevIds = prev.map((b) => b.id).join(',');
        const newIds = foundBoxes.map((b) => b.id).join(',');
        if (prevIds !== newIds || prev.length !== foundBoxes.length) {
          return foundBoxes;
        }
        return prev;
      });
    },
    [currentPage, numPages, findRenderedPageElement]
  );

  // Watch for highlight text changes
  useEffect(() => {
    if (!highlights || highlights.length === 0) {
      setHighlightBoxes([]);
      return;
    }

    const timer = window.setTimeout(() => {
      try {
        computeHighlightsFromDOM(highlights);
      } catch (err) {
        console.error('Error computing highlights from DOM', err);
      }
    }, 180);

    return () => clearTimeout(timer);
  }, [highlights, currentPage, computeHighlightsFromDOM]);

  // Handle document load
  const onDocumentLoadSuccess = (pdf: any) => {
    setNumPages(pdf.numPages);
    pdfRef.current = pdf;
  };

  // Handle page render
  const onPageRenderSuccess = () => {
    if (highlights && highlights.length > 0) {
      setTimeout(() => computeHighlightsFromDOM(highlights), 120);
    }
  };

  return (
    <div className="flex flex-col h-full w-full bg-gray-50 rounded shadow">
      <div
        ref={containerRef}
        className="flex-1 flex justify-center items-center overflow-auto p-2"
      >
        {pdfUrl && (
          <Document
            file={pdfUrl}
            onLoadSuccess={onDocumentLoadSuccess}
            className="w-auto"
          >
            <div style={{ position: 'relative' }}>
              <Page
                pageNumber={currentPage}
                height={containerRef.current ? containerRef.current.clientHeight * 0.97 : undefined}
                onRenderSuccess={onPageRenderSuccess}
                loading="lazy"
              />
              <div
                style={{
                  position: 'absolute',
                  top: 0,
                  left: 0,
                  width: '100%',
                  height: '100%',
                  pointerEvents: 'none',
                  zIndex: 1000,
                }}
              >
                {highlightBoxes
                  .filter((h) => h.page === currentPage)
                  .map((h) => (
                    <div
                      key={h.id}
                      style={{
                        position: 'absolute',
                        left: `${h.left}px`,
                        top: `${h.top}px`,
                        width: `${h.width}px`,
                        height: `${h.height}px`,
                        backgroundColor: h.color,
                        borderRadius: 2,
                        boxShadow: '0 0 0 1px rgba(255,255,0,0.15) inset',
                        border: '1px solid yellow', // Added for visibility
                      }}
                    />
                  ))}
              </div>
            </div>
          </Document>
        )}
      </div>

      <div className="flex justify-center items-center gap-4 mt-2 p-2 border-t bg-white rounded-b">
        <button
          onClick={() => setCurrentPage((prev) => Math.max(1, prev - 1))}
          disabled={currentPage === 1}
          className="p-2 bg-gray-200 disabled:opacity-50 rounded hover:bg-gray-300 transition"
        >
          Prev
        </button>
        <span>
          Page {currentPage} of {numPages}
        </span>
        <button
          onClick={() => setCurrentPage((prev) => Math.min(numPages, prev + 1))}
          disabled={currentPage === numPages}
          className="p-2 bg-gray-200 disabled:opacity-50 rounded hover:bg-gray-300 transition"
        >
          Next
        </button>
      </div>
    </div>
  );
}

export default PDFViewer;